#!/usr/bin/env python3
"""Complete the interactive specification; controls never access a device."""
from pathlib import Path
page=Path(__file__).resolve().parent.parent/'design/v3-preview.html'
text=page.read_text(encoding='utf-8')
start='/* Borealis complete system states */'
end='/* End Borealis complete system states */'
if start in text:
 text=text[:text.index(start)]+text[text.index(end)+len(end):]
extension=r'''
/* Borealis complete system states */
Object.assign(labels,{messages:'Mensagens',camera:'Câmera',gallery:'Galeria',recents:'Recentes',privacy:'Privacidade'});
Object.assign(templates,{
 graphics:()=>`${header('Gráficos')}<div class="sub">Controles independentes · prévia visual</div><div class="group">${toggle('sun','EASU · reconstrução','Desligado por padrão')}</div><div class="hero"><label>Escala de composição<select aria-label="Escala de composição"><option>100%</option><option>77%</option><option selected>67%</option><option>59%</option><option>50%</option><option>33% · experimental</option><option>25% · experimental</option></select></label><p>25% reduz a entrada para 270 × 585. A reconstrução ainda processa a tela inteira e pode custar mais do que economiza.</p></div><div class="group">${toggle('sun','RCAS · nitidez','Independente de EASU e interpolação')}</div><div class="hero"><label>Intensidade RCAS<select aria-label="Intensidade RCAS"><option selected>0% · desativado</option><option>25%</option><option>50%</option><option>75%</option><option>100%</option></select></label><p>O coeficiente é limitado ao intervalo válido. Nitidez não é ganho de desempenho.</p></div><div class="group">${toggle('spark','Interpolação de quadros','Experimental · desligada por padrão')}</div><p class="sub">Estes controles demonstrativos não alteram o celular.</p>`,
 camera:()=>`${header('Câmera')}<div class="viewfinder"><div class="scene"><span></span></div><span class="viewfinder-label">PRÉVIA VISUAL · SEM ACESSO À CÂMERA</span></div><div class="bottom-nav"><button data-demo>Vídeo</button><button aria-pressed="true" data-demo>Foto</button><button data-demo>Retrato</button></div><div class="camera-controls"><button class="small-button" data-go="gallery" aria-label="Abrir galeria">${icon('grid')}</button><button class="shutter" data-demo aria-label="Fotografar na prévia"></button><button class="small-button" data-demo aria-label="Trocar câmera">${icon('camera')}</button></div>`,
 gallery:()=>`${header('Seus momentos')}<div class="sub">Outubro · imagens demonstrativas</div><div class="gallery-grid">${Array.from({length:9},(_,i)=>`<button class="photo" data-go="photo" aria-label="Abrir imagem de aurora ${i+1}" style="--hue:${i*19}deg"></button>`).join('')}</div><div class="bottom-nav"><button data-demo>Fotos</button><button data-demo>Álbuns</button></div>`,
 photo:()=>`${header('Aurora')}<div class="photo large"></div><div class="bottom-nav"><button data-go="share">Compartilhar</button><button data-demo>Editar</button><button data-demo>Excluir</button></div>`,
 conversation:()=>`${header('Borealis')}<div class="sub">Conversa demonstrativa</div><div class="chat"><div class="bubble">Seu novo horizonte está aqui.<small>09:40</small></div><div class="bubble outgoing">Bem-vindo à minha órbita.<small>09:41</small></div></div><label class="composer"><input aria-label="Mensagem" placeholder="Escreva uma mensagem"><button data-demo aria-label="Enviar na prévia">${icon('arrow')}</button></label>`,
 privacy:()=>`${header('Privacidade')}<div class="hero"><div class="small">SUA ÓRBITA É SUA</div><h3>Você escolhe<br>o que compartilhar.</h3><p>Permissões claras, no momento certo.</p></div><div class="group">${row('shield','Gerenciar permissões','Câmera, microfone e localização','permissions')}${toggle('camera','Acesso à câmera','Demonstração do controle de privacidade',true)}${toggle('volume','Acesso ao microfone','Demonstração do controle de privacidade',true)}</div>`,
 permissions:()=>`${header('Permissões')}<div class="group">${row('camera','Câmera','2 aplicativos · exemplo','permission-dialog')}${row('volume','Microfone','1 aplicativo · exemplo','permission-dialog')}${row('phone','Contatos','2 aplicativos · exemplo','permission-dialog')}</div>`,
 'permission-dialog':()=>`${header('Permissão da câmera')}<div class="modal-card">${icon('camera')}<h2>Permitir acesso<br>à câmera?</h2><p>A câmera usa este acesso para fotografar.</p><button data-demo>Durante o uso do app</button><button data-demo>Somente desta vez</button><button data-demo>Não permitir</button></div>`,
 share:()=>`${header('Compartilhar')}<div class="hero"><div class="small">IMAGEM</div><h3>Aurora.png</h3><p>Nenhum arquivo será enviado nesta prévia.</p></div><div class="group">${row('message','Mensagens','Escolher conversa','messages')}${row('bluetooth','Bluetooth','Selecionar dispositivo','connections')}${row('folder','Salvar em Arquivos','Escolher pasta','files')}</div>`,
 recents:()=>`${header('Recentes')}<div class="recent-card"><span class="badge">CONFIGURAÇÕES</span><h2>Seu universo.<br>Do seu jeito.</h2><div class="group">${row('spark','Desempenho e energia','Equilíbrio para seu dia','performance')}${row('sun','Tela e aparência','Aurora','appearance')}</div></div><div class="bottom-nav"><button data-demo>Captura de tela</button><button data-demo>Selecionar</button></div>`,
 connections:()=>`${header('Conexões')}<div class="group">${toggle('wifi','Wi-Fi','Aurora · exemplo',true)}${toggle('bluetooth','Bluetooth','Nenhum dispositivo conectado')}${row('phone','Rede móvel','SIM 1 · demonstração','sim')}${row('wifi','Ponto de acesso','Compartilhamento de conexão','hotspot')}</div>`,
 volume:()=>`${header('Volume')}<div class="group">${['Mídia','Chamadas','Notificações','Alarmes'].map((n,i)=>`<label class="slider">${icon(i===1?'phone':'volume')}<span>${n}</span><input type="range" aria-label="Volume de ${n}" value="${60-i*10}"></label>`).join('')}</div>${toggle('volume','Vibração','Resposta discreta ao toque',true)}`,
 power:()=>`${header('Energia')}<div class="hero"><div class="small">BOREALIS · 82%</div><h3>Cuide do<br>seu horizonte.</h3><p>As ações abaixo são apenas visuais.</p></div><div class="group">${row('battery','Desligar','Prévia sem efeito no aparelho','power-confirm')}${row('orbit','Reiniciar','Prévia sem efeito no aparelho','power-confirm')}</div>`,
 'power-confirm':()=>`${header('Tudo em equilíbrio')}<div class="modal-card"><h2>Ação demonstrativa</h2><p>Nenhum aparelho foi desligado ou reiniciado.</p><button data-go="launcher">Voltar ao início</button></div>`,
 recent:()=>`${header('Chamadas recentes')}<div class="group">${row('phone','Aurora','Hoje, 09:10 · recebida','dialer')}${row('phone','Horizonte','Ontem, 18:30 · realizada','dialer')}</div>`,
 font:()=>`${header('Tipografia')}<h2 style="font-size:38px">Sua órbita.</h2><p>Orbit dá identidade aos títulos. A fonte de sistema mantém a leitura clara no conteúdo e acompanha o tamanho escolhido nas Configurações.</p><label class="slider"><span>Aa</span><input type="range" aria-label="Tamanho de fonte demonstrativo" min="14" max="22" value="15" data-font></label>`,
 'audio-presets':()=>`${header('Seu som')}<div class="group">${['Neutro','Voz','Calor'].map((n,i)=>`<button class="row" data-audio aria-pressed="${i===0}"><span class="row-icon">${icon('music')}</span><strong>${n}</strong><span class="toggle"></span></button>`).join('')}</div><p class="sub">Demonstração visual; o serviço real preserva chamadas e limites do áudio.</p>`,
 about:()=>`${header('BorealisOS')}<div class="hero"><div class="small">AURORA · ALPHA</div><h3>Um novo horizonte.</h3><p>Especificação do visual Android 17 para Galaxy A30. Firmware em desenvolvimento.</p></div><div class="group">${row('orbit','Android 17','SDK 37 · alvo da compilação','about')}${row('spark','Nebula','Eureka R24U · boot em validação','performance')}</div>`,
 cpu:()=>`${header('CPU e GPU')}<div class="hero"><div class="small">HARDWARE PRIMEIRO</div><h3>Limites reais.<br>Controle claro.</h3><p>A tela real só oferecerá frequências positivas anunciadas pelo driver. GPU indisponível ficará desativada com explicação.</p></div><div class="group">${row('spark','CPU','Usar frequência anunciada pelo driver','performance')}${row('grid','GPU','Tabela indisponível neste exemplo','performance')}</div>`,
 memory:()=>`${header('Memória e rede')}<div class="group">${row('grid','Memória comprimida','ZRAM · conforme suporte do kernel','performance')}${row('folder','Entrada e saída','Escalonadores disponíveis','performance')}${row('wifi','Controle TCP','Algoritmos anunciados pelo kernel','connections')}</div>`
});
const originalShow=show;
show=function(name){originalShow(name);phone.classList.toggle('boot-full',name==='boot');screen.setAttribute('aria-label',labels[name]||'Tela '+name);if(name==='appearance'){const switches=screen.querySelectorAll('[data-toggle]');switches[0].dataset.setting='theme';switches[1].dataset.setting='motion';}};
function applyMotion(){phone.classList.toggle('reduced',reduce);document.querySelector('#motion').setAttribute('aria-pressed',reduce);}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
 if(b.dataset.setting==='theme')document.querySelector('#theme').click();
 if(b.dataset.setting==='motion'){reduce=b.getAttribute('aria-pressed')==='true';applyMotion();}
 if(b.id==='motion')applyMotion();
 if(b.hasAttribute('data-demo'))toast('Ação demonstrativa; nenhum dado foi alterado');
 if(b.hasAttribute('data-audio'))screen.querySelectorAll('[data-audio]').forEach(n=>n.setAttribute('aria-pressed',n===b));
});
document.addEventListener('input',e=>{if(e.target.hasAttribute('data-font'))screen.style.fontSize=e.target.value+'px';});
/* End Borealis complete system states */
'''
anchor='function show(name)'
text=text.replace(anchor,extension+'\n'+anchor,1)
css='''
.phone.boot-full .status,.phone.boot-full .gesture{display:none}.phone.boot-full .screen{height:100%;padding:0}.phone.boot-full .camera{display:none}
.viewfinder{height:360px;border-radius:28px;background:#0a1520;position:relative;overflow:hidden}.scene{height:100%;background:radial-gradient(ellipse at 70% 25%,#94d4bb66,transparent 65%),linear-gradient(160deg,#294855,#152c35 50%,#071519)}.scene span{position:absolute;bottom:-10px;width:130%;height:160px;background:#122521;transform:rotate(-12deg);border-radius:50%}.viewfinder-label{position:absolute;bottom:14px;left:15px;color:#fff;font-size:9px;letter-spacing:.08em}.camera-controls{display:flex;align-items:center;justify-content:space-around;margin-top:22px}.shutter{width:72px;height:72px;border-radius:50%;background:#f2f3ff;border:5px solid #8be8d0;box-shadow:inset 0 0 0 5px #090d15}.gallery-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:6px;margin-top:24px}.photo{aspect-ratio:1;border-radius:16px;background:radial-gradient(ellipse at 70% 25%,#8be8d077,transparent 50%),linear-gradient(150deg,#36324b,#29484c 45%,#152422);filter:hue-rotate(var(--hue,0deg))}.photo.large{aspect-ratio:3/4;margin:25px 0}.chat{min-height:420px;display:flex;flex-direction:column;gap:16px;padding-top:30px}.bubble{align-self:flex-start;max-width:88%;padding:16px;background:var(--surface);border-radius:24px 24px 24px 8px}.bubble.outgoing{align-self:flex-end;background:var(--accent);color:var(--on-accent);border-radius:24px 24px 8px 24px}.bubble small{display:block;font-size:10px;margin-top:8px;opacity:.75}.composer{display:flex;gap:10px;border:1px solid var(--line);border-radius:26px;padding:8px 12px;background:var(--surface)}.composer input{background:none;color:var(--text);border:0;min-width:0;flex:1}.composer button{width:44px;height:44px;background:var(--accent);color:var(--on-accent);border-radius:50%;transform:rotate(180deg)}.modal-card{background:var(--surface);padding:24px;border:1px solid var(--line);border-radius:28px;margin-top:90px}.modal-card p{color:var(--muted);font-size:14px}.modal-card>button{width:100%;min-height:52px;border-radius:20px;margin-top:8px;background:var(--accent);color:var(--on-accent)}.modal-card>button:last-child{background:var(--bg);color:var(--text)}.recent-card{border-radius:30px;background:var(--surface);padding:22px;margin:30px 0 20px;min-height:440px;box-shadow:0 12px 32px #0003}.reduced button{transform:none!important}
'''
if '.viewfinder{height:360px' not in text:text=text.replace('</style>',css+'\n</style>',1)
text=text.replace("${toggle('sun','FSR 1 · EASU + RCAS','Experimental · desligado por padrão')}${toggle('spark','Interpolação de quadros','Experimental · pode adicionar latência')}", "${row('sun','EASU, RCAS e interpolação','Três controles independentes','graphics')}")
page.write_text(text,encoding='utf-8')
print('Preview expanded with camera, gallery, permissions, sharing, recents and fullscreen boot.')
